{
  "items": [
    {
      "title": "Eurostat – ICT Usage in Enterprises (isoc_e)",
      "url_or_doi": "https://ec.europa.eu/eurostat/cache/metadata/en/isoc_e_esms.htm",
      "justification": "An official Eurostat dataset covering the adoption and use of information and communication technologies (ICT) by businesses in Germany and other European countries. Includes annual statistics on internet connectivity, e-commerce, cloud computing, enterprise software, cybersecurity, and emerging digital technologies. Particularly relevant for studying German business digitalisation during the 2010s and 2020s. Data can be filtered by country, year, industry, and enterprise size."
    },
    {
      "title": "Eurostat – ICT Usage in Households and by Individuals (isoc_i)",
      "url_or_doi": "https://ec.europa.eu/eurostat/cache/metadata/en/isoc_i_esms.htm",
      "justification": "A comprehensive annual dataset covering internet access, computer usage, digital skills, online shopping, e-government services, and other ICT activities among German households and individuals. The survey has operated in Germany since 2002, providing extensive historical coverage of both the 2010s and 2020s. Particularly useful for analysing digital inclusion, technology adoption, and changes in internet behaviour."
    },
    {
      "title": "Eurostat – Digital Economy and Society Database",
      "url_or_doi": "https://ec.europa.eu/eurostat/web/digital-economy-and-society/information-data",
      "justification": "An official European statistical resource containing multiple datasets about information technology and digital transformation. Covers internet connectivity, ICT usage, electronic commerce, digital skills, and enterprise digitalisation. Includes Germany-specific observations across the 2010s and 2020s, making it suitable for constructing longitudinal datasets and comparing Germany with other European countries."
    },
    {
      "title": "German Federal Statistical Office (Destatis) – ICT Indicators for Enterprises in Germany",
      "url_or_doi": "https://www.govdata.de/suche/daten/ikt-indikatoren-fur-unternehmen-deutschland-jahre-bis-202406611",
      "justification": "An official German government dataset titled 'IKT-Indikatoren für Unternehmen: Deutschland, Jahre (bis 2024).' Provides national statistics on information and communication technology usage among German enterprises. Especially relevant for examining technology adoption, business digitalisation, and changes in ICT infrastructure over time. Its Germany-specific focus makes it particularly valuable for national research."
    },
    {
      "title": "OECD – ICT Access and Usage by Businesses",
      "url_or_doi": "https://data-explorer.oecd.org/vis?df%5Bag%5D=OECD.STI.DEP&df%5Bds%5D=dsDisseminateFinalDMZ&df%5Bid%5D=DSD_ICT_B%40DF_BUSINESSES&df%5Bvs%5D=1.0&dq=.A.A1_B.._T.S_GE10%2BS_GE100&lc=en&pd=2012%2C&pg=0&snb=60&tm=ICT+access&to%5BTIME_PERIOD%5D=false",
      "justification": "An OECD statistical database containing approximately 60 indicators measuring ICT adoption and usage by businesses. Covers technologies such as computers, internet connections, and digital business applications. Includes Germany and other OECD economies, with observations extending across the 2010s and 2020s. Useful for comparing Germany's technological development with other industrialised countries and investigating differences by enterprise size and economic activity."
    },
    {
      "title": "Eurostat – Survey on ICT Usage in Households and by Individuals: Scientific-Use Microdata",
      "url_or_doi": "https://ec.europa.eu/eurostat/web/microdata/collections-research/survey-ict-use-households-individuals",
      "justification": "Provides access to partially anonymised individual-level survey datasets for reference years 2008–2025, subject to country availability and research-access requirements. Includes information about internet access, e-commerce, digital literacy, online security, cloud services, and the Internet of Things. Particularly valuable for researchers requiring microdata rather than aggregated statistics. Enables investigation of demographic, socioeconomic, and regional differences in ICT adoption within Germany."
    },
    {
      "title": "Eurostat – Level of Internet Access in Households",
      "url_or_doi": "https://ec.europa.eu/eurostat/databrowser/view/tin00134/bookmark/table?bookmarkId=4747b5a6-24ea-4f0b-8b39-de751bc4f2d3&lang=en",
      "justification": "A Eurostat statistical table measuring household internet access across European countries, including Germany. Based on the annual European survey of ICT usage in households and by individuals. Suitable for studying changes in internet penetration during the 2010s and 2020s, identifying trends in household connectivity, and comparing Germany's digital infrastructure adoption with other European economies."
    },
    {
      "title": "Eurostat – Comprehensive Digital Economy and Society Database",
      "url_or_doi": "https://ec.europa.eu/eurostat/de/web/digital-economy-and-society/database/comprehensive-database",
      "justification": "A comprehensive collection of European ICT statistics that provides access to detailed indicators and downloadable statistical data. Contains information on ICT adoption in enterprises, internet usage among households, digital technologies, and electronic commerce. Particularly suitable for researchers seeking to assemble Germany-specific time series covering the 2010s and 2020s using consistent European statistical definitions."
    },
    {
      "title": "Eurostat – ICT Usage in Enterprises: German National Reference Metadata and Data",
      "url_or_doi": "https://ec.europa.eu/eurostat/cache/metadata/en/isoc_e_simsie_de.htm",
      "justification": "Germany-specific documentation for the official Eurostat ICT enterprise statistics, compiled by the German Federal Statistical Office. Describes the national survey methodology, statistical population, collection procedures, and quality characteristics of German enterprise ICT data. Especially useful for interpreting German observations in the annual ICT enterprise datasets and assessing the comparability of data across the 2010s and 2020s."
    },
    {
      "title": "Eurostat – ICT Usage in Households and by Individuals: German National Reference Metadata",
      "url_or_doi": "https://ec.europa.eu/eurostat/cache/metadata/EN/isoc_i_simsih2_de.htm",
      "justification": "Official German reference documentation for the annual ICT household and individual usage survey. Confirms that Germany has participated in the survey since 2002 and describes the collection of information on internet use, digital skills, e-commerce, e-government, privacy, and ICT access. Useful for understanding methodological changes and evaluating the reliability of longitudinal analyses of German digitalisation between 2010 and 2025."
    }
  ]
}
